public class CopaAllocationRun extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="rule_id",nullable=false) CopaAllocationRule rule; @Column(name="fiscal_year",nullable=false) Integer fiscalYear; @Column(name="period_number",nullable=false) Integer periodNumber; @Column(name="allocated_amount",nullable=false,precision=19,scale=2) BigDecimal allocatedAmount; @Column(nullable=false,length=20) String status; @Column(name="run_at",nullable=false) LocalDateTime runAt; @Column(name="run_by",nullable=false,length=100) String runBy; }